def count_plaque_arrangements(n, k):
    # Initialize the DP table
    dp = [[0] * (1 << n) for _ in range(n)]

    # Base case: all houses can reach house 1
    for i in range(n):
        dp[i][0] = 1

    # Fill the DP table
    for mask in range(1, 1 << n):
        for i in range(n):
            if not (mask & (1 << i)):
                continue
            for j in range(n):
                if mask & (1 << j):
                    continue
                new_mask = mask | (1 << j)
                dp[i][new_mask] = (dp[i][new_mask] + dp[j][mask]) % MOD

    # Count valid arrangements
    total = 0
    for i in range(n):
        reachable = 0
        for mask in range(1 << n):
            if mask & (1 << i):
                reachable = (reachable + dp[i][mask]) % MOD

        if i < k:
            total = (total + reachable) % MOD
        else:
            total = (total + (MOD - reachable)) % MOD

    return total

